export interface ScenarioEvent {
  t: number;
  kind: 'press' | 'set' | 'spawn' | 'pick' | 'stick' | 'unstick';
  input?: InputName; // press: momentary button; set: maintained input (ESTOP, GUARD_CLOSED)
  value?: 0 | 1; // set / stick
