1	// The digital twin: PLC + conveyor plant + safety monitors, stepped one scan at a time.
2	// Used both by the scenario runner (scripted tests, parity with agent/plc/sim.py) and by
3	// Play mode (live, interactive).
4	
5	import type { Frame, Rung, Scenario, ScenarioEvent, Trace, TraceEvent, Violation } from '../types';
6	import { OUTPUT_NAMES } from './lang';
7	import { Monitor } from './monitors';
8	import { DT, Plc, initialInputs, type Bit } from './plc';
9	import { CONVENTIONS, Plant, type Sensor } from './plant';
10	
11	export const round1 = (x: number): number => Math.round(x * 10) / 10;
12	
13	export interface SimOptions {
14	  autofeedEvery?: number;
15	  autopickAfter?: number;
16	}
17	
18	export interface StepResult {
19	  frame: Frame;
20	  violations: Violation[];
21	  events: TraceEvent[];
22	}
23	
24	const PRESS_LABEL: Record<string, string> = {
25	  START: 'Operator presses START',
26	  STOP: 'Operator presses STOP',
27	  RESET: 'Operator presses RESET',
28	  ESTOP: 'E-stop pressed',
29	};
30	
31	function setLabel(input: string, v: Bit): string {
32	  if (input === 'ESTOP') return v ? 'E-stop pressed' : 'E-stop released';
33	  if (input === 'GUARD_CLOSED') return v ? 'Guard door closed' : 'Guard door opened';
34	  return v ? `Operator holds ${input}` : `Operator releases ${input}`;
35	}
36	
37	export class Sim {
38	  readonly dt = DT;
39	  plc: Plc;
40	  plant = new Plant();
41	  mon = new Monitor();
42	  inputs: Record<string, Bit> = initialInputs();
43	  k = 0; // index of the next scan
44	  opts: SimOptions;
45	  lastOut: Record<string, Bit> = Object.fromEntries(OUTPUT_NAMES.map((n) => [n, 0 as Bit]));
46	  pickWait = 0; // scans a box has waited at the pick position with the belt stopped
47	  private releases: { input: string; at: number }[] = [];
48	  private lastSpawnT = -Infinity;
49	  private pending: TraceEvent[] = [];
50	
51	  constructor(program: Rung[], opts: SimOptions = {}) {
52	    this.plc = new Plc(program);
53	    this.opts = { ...opts };
54	  }
55	
56	  /** Time of the next scan. */
57	  get t(): number {
58	    return round1(this.k * this.dt);
59	  }
60	
61	  private ev(kind: TraceEvent['kind'], label: string): void {
62	    this.pending.push({ t: this.t, kind, label });
63	  }
64	
65	  // ---- actions (take effect at the next scan) ----
66	
67	  /** Momentary press: 1 now, back to 0 at the first scan with t >= from + duration. */
68	  press(input: string, duration = 0.3, from = this.t): void {
69	    this.releases = this.releases.filter((r) => r.input !== input);
70	    this.inputs[input] = 1;
71	    this.releases.push({ input, at: from + duration });
72	    this.ev('press', PRESS_LABEL[input] ?? `Operator presses ${input}`);
73	  }
74	
75	  /** Hold a button until release() (Play mode). */
76	  hold(input: string): void {
77	    this.releases = this.releases.filter((r) => r.input !== input);
78	    if (this.inputs[input] !== 1) this.ev('press', PRESS_LABEL[input] ?? `Operator presses ${input}`);
79	    this.inputs[input] = 1;
80	  }
81	
82	  /** Release a held button, keeping it pressed for at least `min` seconds after `since`. */
83	  release(input: string, since: number, min = 0.3): void {
84	    this.releases = this.releases.filter((r) => r.input !== input);
85	    this.releases.push({ input, at: Math.max(since + min, this.t) });
86	  }
87	
88	  set(input: string, v: Bit): void {
89	    if (this.inputs[input] === v) return;
90	    this.inputs[input] = v;
91	    this.ev('set', setLabel(input, v));
92	  }
93	
94	  spawn(scripted = false): boolean {
95	    const b = this.plant.spawn();
96	    if (b) this.ev('spawn', 'Box placed on infeed');
97	    if (b && scripted && CONVENTIONS.explicitSpawnResetsAutofeed) this.lastSpawnT = this.t;
98	    return !!b;
99	  }
100	
101	  pick(): boolean {
102	    const b = this.plant.pick();
103	    if (b) this.ev('pick', 'Robot picks box');
104	    return !!b;
105	  }
106	
107	  stick(sensor: Sensor, v: Bit): void {
108	    this.plant.stuck[sensor] = v;
109	    this.ev('stick', `${sensor} sensor stuck ${v ? 'ON' : 'OFF'}`);
110	  }
111	
112	  unstick(sensor: Sensor): void {
113	    if (this.plant.stuck[sensor] === undefined) return;
114	    delete this.plant.stuck[sensor];
115	    this.ev('unstick', `${sensor} sensor repaired`);
116	  }
117	
118	  applyEvent(e: ScenarioEvent): void {
119	    switch (e.kind) {
120	      case 'press':
121	        if (e.input) this.press(e.input, e.duration ?? 0.3, e.t);
122	        break;
123	      case 'set':
124	        if (e.input) this.set(e.input, (e.value ?? 1) as Bit);
125	        break;
126	      case 'spawn':
127	        this.spawn(true);
128	        break;
129	      case 'pick':
130	        this.pick();
131	        break;
132	      case 'stick':
133	        if (e.sensor) this.stick(e.sensor, (e.value ?? 1) as Bit);
134	        break;
135	      case 'unstick':
136	        if (e.sensor) this.unstick(e.sensor);
137	        break;
138	    }
139	  }
140	
141	  /** Swap the program, keeping plant and memory ("online change"). */
142	  loadProgram(program: Rung[], reset = false): void {
143	    this.plc.load(program, reset);
144	  }
145	
146	  // ---- one scan ----
147	
148	  step(applyEvents?: (sim: Sim, t: number) => void): StepResult {
149	    const t = this.t;
150	    const dt = this.dt;
151	
152	    // 1. operator / plant events
153	    this.releases = this.releases.filter((r) => {
154	      if (t >= r.at) {
155	        this.inputs[r.input] = 0;
156	        this.ev('release', `${r.input} released`);
157	        return false;
158	      }
159	      return true;
160	    });
161	    applyEvents?.(this, t);
162	    const feed = this.opts.autofeedEvery;
163	    if (feed != null && feed > 0 && t - this.lastSpawnT >= feed && this.plant.infeedClear()) {
164	      if (this.spawn()) this.lastSpawnT = t;
165	    }
166	    const pickAfter = this.opts.autopickAfter;
167	    if (pickAfter != null && pickAfter >= 0) {
168	      const b = this.plant.atPick();
169	      if (b && this.lastOut.MOTOR === 0) {
170	        this.pickWait++;
171	        if (this.pickWait >= Math.round(pickAfter / dt) + CONVENTIONS.autopickExtraScans) {
172	          this.pick();
173	          this.pickWait = 0;
174	        }
175	      } else this.pickWait = 0;
176	    }
177	
178	    // 2. sensors from box positions (start of scan) and forcing
179	    const s = this.plant.sensors();
180	    this.inputs.PE_IN = s.PE_IN;
181	    this.inputs.PE_END = s.PE_END;
182	
183	    // 3. PLC scan
184	    this.plc.scan(this.inputs, dt);
185	    const out = this.plc.outputs();
186	
187	    // 4. monitors
188	    const violations = this.mon.check(t, this.inputs, out);
189	
190	    // 5. record
191	    const frame: Frame = {
192	      t,
193	      in: { ...this.inputs },
194	      out,
195	      coil: this.plc.coilValues(),
196	      timer: this.plc.timerValues(),
197	      boxes: this.plant.snapshot(),
198	    };
199	    if (Object.keys(this.plant.stuck).length) frame.stuck = { ...this.plant.stuck };
200	
201	    // 6. move the belt
202	    if (out.MOTOR === 1) {
203	      for (const b of this.plant.move()) {
204	        violations.push({ rule: 'DROP', t, message: `Box #${b.id} pushed off the end of the belt` });
205	        this.ev('drop', `Box #${b.id} falls off the end`);
206	      }
207	    }
208	    this.lastOut = out;
209	    this.k++;
210	    const events = this.pending;
211	    this.pending = [];
212	    return { frame, violations, events };
213	  }
214	}
215	
216	/** Run a scripted scenario and record its full trace. */
217	export function runScenario(program: Rung[], sc: Scenario): Trace {
218	  const sim = new Sim(program, { autofeedEvery: sc.options?.autofeed_every, autopickAfter: sc.options?.autopick_after });
219	  const n = Math.round(sc.duration / DT);
220	  const applied = sc.events.map(() => false);
221	  const trace: Trace = { dt: DT, frames: [], violations: [], events: [] };
222	  const apply = (s: Sim, t: number): void => {
223	    sc.events.forEach((e, i) => {
224	      if (!applied[i] && e.t <= t + 1e-9) {
225	        applied[i] = true;
226	        s.applyEvent(e);
227	      }
228	    });
229	  };
230	  for (let k = 0; k < n; k++) {
231	    const r = sim.step(apply);
232	    trace.frames.push(r.frame);
233	    trace.violations.push(...r.violations);
234	    trace.events.push(...r.events);
235	  }
236	  return trace;
237	}
