1	// Conveyor plant in integer millimetres (exact parity with agent/plc/plant.py).
2	
3	import type { Bit } from './plc';
4	
5	export type BoxState = 'belt' | 'picked' | 'dropped';
6	export interface PlantBox {
7	  id: number;
8	  x: number; // centre, mm
9	  state: BoxState;
10	}
11	
12	export const GEO = {
13	  beltEnd: 4000,
14	  step: 50, // mm per scan while MOTOR = 1 (0.5 m/s at dt = 0.1 s)
15	  boxLen: 400,
16	  spawnX: 200,
17	  peIn: 300,
18	  peEnd: 3700,
19	  sense: 200, // a photo-eye sees a box whose centre is within this distance
20	  dropX: 3900,
21	  pickX: 3700,
22	  pickHalf: 250,
23	} as const;
24	
25	export type Sensor = 'PE_IN' | 'PE_END';
26	
27	/**
28	 * Details the written spec leaves open. The defaults are our best reading of agent/plc;
29	 * scripts/parity.ts tries the alternatives when a golden trace disagrees and reports which one matches.
30	 */
31	export const CONVENTIONS = {
32	  firstBoxId: 1, // id of the first box spawned
33	  autopickExtraScans: 0, // autopick fires after round(N / dt) + this many waiting scans
34	  explicitSpawnResetsAutofeed: false, // does a scripted spawn restart the autofeed interval?
35	};
36	
37	export class Plant {
38	  boxes: PlantBox[] = [];
39	  nextId = CONVENTIONS.firstBoxId;
40	  stuck: Partial<Record<Sensor, Bit>> = {};
41	
42	  infeedClear(): boolean {
43	    return !this.boxes.some((b) => b.state === 'belt' && Math.abs(b.x - GEO.spawnX) < GEO.boxLen);
44	  }
45	
46	  spawn(): PlantBox | null {
47	    if (!this.infeedClear()) return null;
48	    const b: PlantBox = { id: this.nextId++, x: GEO.spawnX, state: 'belt' };
49	    this.boxes.push(b);
50	    return b;
51	  }
52	
53	  /** The belt box at the pick position (the leading one if two qualify). */
54	  atPick(): PlantBox | undefined {
55	    let best: PlantBox | undefined;
56	    for (const b of this.boxes)
57	      if (b.state === 'belt' && Math.abs(b.x - GEO.pickX) <= GEO.pickHalf && (!best || b.x > best.x)) best = b;
58	    return best;
59	  }
60	
61	  pick(): PlantBox | null {
62	    const b = this.atPick();
63	    if (!b) return null;
64	    b.state = 'picked';
65	    return b;
66	  }
67	
68	  sees(pos: number): Bit {
69	    return this.boxes.some((b) => b.state === 'belt' && Math.abs(b.x - pos) <= GEO.sense) ? 1 : 0;
70	  }
71	
72	  sensors(): Record<Sensor, Bit> {
73	    return {
74	      PE_IN: this.stuck.PE_IN ?? this.sees(GEO.peIn),
75	      PE_END: this.stuck.PE_END ?? this.sees(GEO.peEnd),
76	    };
77	  }
78	
79	  /** Move every belt box one scan forward. Returns the boxes that fell off the end. */
80	  move(): PlantBox[] {
81	    const belt = this.boxes.filter((b) => b.state === 'belt').sort((a, b) => b.x - a.x);
82	    const dropped: PlantBox[] = [];
83	    let ahead: PlantBox | null = null;
84	    for (const b of belt) {
85	      let nx = b.x + GEO.step;
86	      if (ahead) nx = Math.min(nx, ahead.x - GEO.boxLen);
87	      b.x = nx;
88	      if (b.x > GEO.dropX) {
89	        b.state = 'dropped';
90	        dropped.push(b);
91	      }
92	      ahead = b;
93	    }
94	    return dropped;
95	  }
96	
97	  snapshot(): { id: number; x: number; state: BoxState }[] {
98	    return this.boxes.map((b) => ({ id: b.id, x: b.x / 1000, state: b.state }));
99	  }
100	}
