1	// PLC scan engine. Mirrors agent/plc: rungs run top to bottom every scan, expressions read the
2	// current memory (so a coil written by an earlier rung this scan is already updated), RISE(X)
3	// compares against the memory snapshot taken at the end of the previous scan.
4	
5	import type { Expr, Rung } from '../types';
6	import { INPUT_NAMES, OUTPUT_NAMES, exprRefs, isInput, isOutput } from './lang';
7	
8	export type Bit = 0 | 1;
9	
10	export interface TimerState {
11	  et: number; // elapsed seconds
12	  q: boolean;
13	  pt: number; // preset seconds
14	}
15	
16	export const DT = 0.1;
17	
18	/** Initial input values: everything released, guard door closed. */
19	export function initialInputs(): Record<string, Bit> {
20	  const m: Record<string, Bit> = {};
21	  for (const n of INPUT_NAMES) m[n] = 0;
22	  m.GUARD_CLOSED = 1;
23	  return m;
24	}
25	
26	/** Read-only view of PLC memory, used by the evaluator and by the ladder power-flow view. */
27	export interface MemoryView {
28	  get(name: string): Bit;
29	  prev(name: string): Bit;
30	  timerQ(name: string): boolean;
31	}
32	
33	export function evalExpr(e: Expr, m: MemoryView): boolean {
34	  switch (e.op) {
35	    case 'var':
36	      return m.get(e.name) === 1;
37	    case 'timer':
38	      return m.timerQ(e.name);
39	    case 'rise':
40	      return m.get(e.name) === 1 && m.prev(e.name) !== 1;
41	    case 'const':
42	      return e.value;
43	    case 'not':
44	      return !evalExpr(e.arg, m);
45	    case 'and':
46	      for (const a of e.args) if (!evalExpr(a, m)) return false;
47	      return true;
48	    case 'or':
49	      for (const a of e.args) if (evalExpr(a, m)) return true;
50	      return false;
51	  }
52	}
53	
54	/** Internal coils of a program (not inputs, not outputs, not timers), in order of first appearance. */
55	export function programCoils(rungs: Rung[]): string[] {
56	  const out: string[] = [];
57	  const seen = new Set<string>();
58	  const add = (n: string): void => {
59	    if (isInput(n) || isOutput(n) || seen.has(n)) return;
60	    seen.add(n);
61	    out.push(n);
62	  };
63	  for (const r of rungs) if (r.kind !== 'ton') add(r.target);
64	  for (const r of rungs) exprRefs(r.expr).vars.forEach(add);
65	  return out;
66	}
67	
68	export function programTimers(rungs: Rung[]): { name: string; pt: number }[] {
69	  const out: { name: string; pt: number }[] = [];
70	  for (const r of rungs) if (r.kind === 'ton' && !out.some((t) => t.name === r.target)) out.push({ name: r.target, pt: r.pt ?? 0 });
71	  return out;
72	}
73	
74	export class Plc implements MemoryView {
75	  rungs: Rung[] = [];
76	  sig: Record<string, Bit> = {};
77	  prevSig: Record<string, Bit> = {};
78	  timers: Record<string, TimerState> = {};
79	  coils: string[] = [];
80	  timerNames: string[] = [];
81	
82	  constructor(rungs: Rung[]) {
83	    this.load(rungs, true);
84	  }
85	
86	  /** Load a program. With reset=false the memory is kept (an "online change"); new names start at 0. */
87	  load(rungs: Rung[], reset: boolean): void {
88	    this.rungs = rungs;
89	    this.coils = programCoils(rungs);
90	    const timers = programTimers(rungs);
91	    this.timerNames = timers.map((t) => t.name);
92	    if (reset) {
93	      this.sig = { ...initialInputs() };
94	      this.prevSig = { ...initialInputs() };
95	      for (const n of OUTPUT_NAMES) this.sig[n] = this.prevSig[n] = 0;
96	      this.timers = {};
97	    }
98	    for (const n of this.coils) {
99	      if (this.sig[n] === undefined) this.sig[n] = 0;
100	      if (this.prevSig[n] === undefined) this.prevSig[n] = 0;
101	    }
102	    const next: Record<string, TimerState> = {};
103	    for (const t of timers) {
104	      const old = this.timers[t.name];
105	      next[t.name] = old ? { et: Math.min(old.et, t.pt), q: old.et >= t.pt - 1e-9, pt: t.pt } : { et: 0, q: false, pt: t.pt };
106	    }
107	    this.timers = next;
108	  }
109	
110	  get(name: string): Bit {
111	    return this.sig[name] === 1 ? 1 : 0;
112	  }
113	  prev(name: string): Bit {
114	    return this.prevSig[name] === 1 ? 1 : 0;
115	  }
116	  timerQ(name: string): boolean {
117	    return this.timers[name]?.q ?? false;
118	  }
119	
120	  /** One scan: latch the inputs, execute every rung in order, then snapshot memory for RISE(). */
121	  scan(inputs: Record<string, Bit>, dt = DT): void {
122	    for (const n of INPUT_NAMES) this.sig[n] = inputs[n] === 1 ? 1 : 0;
123	    for (const r of this.rungs) {
124	      const v = evalExpr(r.expr, this);
125	      switch (r.kind) {
126	        case 'assign':
127	          this.sig[r.target] = v ? 1 : 0;
128	          break;
129	        case 'set':
130	          if (v) this.sig[r.target] = 1;
131	          break;
132	        case 'reset':
133	          if (v) this.sig[r.target] = 0;
134	          break;
135	        case 'ton': {
136	          const tm = this.timers[r.target];
137	          const pt = r.pt ?? 0;
138	          if (v) tm.et = Math.min(tm.et + dt, pt);
139	          else tm.et = 0;
140	          tm.q = tm.et >= pt - 1e-9;
141	          break;
142	        }
143	      }
144	    }
145	    this.prevSig = { ...this.sig };
146	  }
147	
148	  outputs(): Record<string, Bit> {
149	    const o: Record<string, Bit> = {};
150	    for (const n of OUTPUT_NAMES) o[n] = this.get(n);
151	    return o;
152	  }
153	
154	  coilValues(): Record<string, Bit> {
155	    const o: Record<string, Bit> = {};
156	    for (const n of this.coils) o[n] = this.get(n);
157	    return o;
158	  }
159	
160	  timerValues(): Record<string, number> {
161	    const o: Record<string, number> = {};
162	    for (const n of this.timerNames) o[n] = this.timers[n].et;
163	    return o;
164	  }
165	}
