1	// Runtime safety monitors (observers), evaluated every scan on that scan's inputs and outputs.
2	// Mirrors agent/plc/monitors.py. A rule is reported once per contiguous violating stretch.
3	
4	import type { Violation } from '../types';
5	import type { Bit } from './plc';
6	
7	export const RULE_IDS = ['S1', 'S2', 'S3', 'S4', 'S5', 'S6', 'S7'] as const;
8	export type RuleId = (typeof RULE_IDS)[number];
9	
10	export const RULE_TITLES: Record<string, string> = {
11	  S1: 'E-stop stops the belt',
12	  S2: 'Open guard stops the belt',
13	  S3: 'STOP dominates',
14	  S4: 'No automatic restart',
15	  S5: 'E-stop needs a reset',
16	  S6: 'Stop at the pick position',
17	  S7: 'Jam supervision',
18	  DROP: 'Box dropped',
19	};
20	
21	export const RULE_MESSAGES: Record<string, string> = {
22	  S1: 'Motor running while the E-stop is pressed',
23	  S2: 'Motor running with the guard door open',
24	  S3: 'Motor running while STOP is pressed',
25	  S4: 'Motor restarted without a START press',
26	  S5: 'E-stop cleared without RESET',
27	  S6: 'Motor running with a box at the pick position',
28	  S7: 'Infeed jam not detected within 3.5 s',
29	};
30	
31	/** Short "what it looks like on the floor" consequence, used in toasts. */
32	export const RULE_CONSEQUENCE: Record<string, string> = {
33	  S1: 'belt kept moving through an E-stop',
34	  S2: 'belt moving with the guard open',
35	  S3: 'STOP ignored',
36	  S4: 'belt restarted by itself',
37	  S5: 'E-stop lock-out lost',
38	  S6: 'box carried past the robot',
39	  S7: 'jam went undetected',
40	  DROP: 'box pushed off the end',
41	};
42	
43	export class Monitor {
44	  armed: Bit = 0;
45	  lock: Bit = 0;
46	  jam = 0;
47	  private prevStart: Bit = 0;
48	  private prevReset: Bit = 0;
49	  private active: Record<string, boolean> = {};
50	
51	  check(t: number, inp: Record<string, Bit>, out: Record<string, Bit>): Violation[] {
52	    const START = inp.START === 1;
53	    const STOP = inp.STOP === 1;
54	    const ESTOP = inp.ESTOP === 1;
55	    const RESET = inp.RESET === 1;
56	    const GUARD = inp.GUARD_CLOSED === 1;
57	    const PE_IN = inp.PE_IN === 1;
58	    const PE_END = inp.PE_END === 1;
59	    const MOTOR = out.MOTOR === 1;
60	    const RED = out.LAMP_RED === 1;
61	    const riseStart = START && this.prevStart === 0;
62	    const riseReset = RESET && this.prevReset === 0;
63	
64	    const lock = (this.lock === 1 || ESTOP) && !(!ESTOP && riseReset);
65	    this.lock = lock ? 1 : 0;
66	    const armed = (this.armed === 1 || (riseStart && !lock)) && !STOP && !ESTOP && GUARD && !RED;
67	    this.armed = armed ? 1 : 0;
68	    this.jam = MOTOR && PE_IN ? this.jam + 1 : 0;
69	
70	    const cond: Record<RuleId, boolean> = {
71	      S1: ESTOP && MOTOR,
72	      S2: !GUARD && MOTOR,
73	      S3: STOP && MOTOR,
74	      S4: MOTOR && !armed,
75	      S5: lock && (MOTOR || !RED),
76	      S6: PE_END && MOTOR,
77	      S7: this.jam > 35,
78	    };
79	    const out_: Violation[] = [];
80	    for (const id of RULE_IDS) {
81	      const v = cond[id];
82	      if (v && !this.active[id]) out_.push({ rule: id, t, message: RULE_MESSAGES[id] });
83	      this.active[id] = v;
84	    }
85	    this.prevStart = START ? 1 : 0;
86	    this.prevReset = RESET ? 1 : 0;
87	    return out_;
88	  }
89	
90	  /** Rules currently in a violating stretch. */
91	  activeRules(): string[] {
92	    return RULE_IDS.filter((id) => this.active[id]);
93	  }
94	}
