"""The restricted control language ("ladder-lite"): tokenizer, parser, printer and validator.

    rung   := NAME '=' expr | 'SET' NAME 'WHEN' expr | 'RESET' NAME 'WHEN' expr
            | 'TON' TNAME '(' expr ',' NUMBER 's' ')'
    expr   := term ('OR' term)*
    term   := factor ('AND' factor)*
    factor := 'NOT' factor | '(' expr ')' | 'RISE' '(' NAME ')' | TNAME '.Q' | NAME | 'TRUE' | 'FALSE'

The AST matches web/src/types.ts (Expr, Rung) so programs can be exported to the viewer as-is.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

INPUTS = ("START", "STOP", "ESTOP", "RESET", "GUARD_CLOSED", "PE_IN", "PE_END")
OUTPUTS = ("MOTOR", "LAMP_GREEN", "LAMP_AMBER", "LAMP_RED")
RESERVED = {"NOT", "AND", "OR", "TRUE", "FALSE", "WHEN", "RISE", "TON"}

# Limits that keep agent patches small and the state space checkable.
MAX_RUNGS = 24
MAX_COILS = 12
MAX_TIMERS = 4
MAX_LITERALS = 12
PT_MIN, PT_MAX = 0.1, 10.0

_TOKEN = re.compile(r"\s*(?:(\d+(?:\.\d+)?s?)|([A-Z][A-Z0-9_]*(?:\.Q)?)|(\(|\)|,|=))")


class ParseError(ValueError):
    pass


def is_timer_name(name: str) -> bool:
    return re.fullmatch(r"T_[A-Z0-9_]+", name) is not None


def _tokenize(text: str) -> list[str]:
    tokens: list[str] = []
    pos = 0
    text = text.strip()
    while pos < len(text):
        m = _TOKEN.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"unexpected character {text[pos]!r} at column {pos + 1}")
        tokens.append(m.group(m.lastindex))
        pos = m.end()
        while pos < len(text) and text[pos].isspace():
            pos += 1
    return tokens


class _Parser:
    def __init__(self, tokens: list[str]):
        self.toks = tokens
        self.i = 0

    def peek(self) -> str | None:
        return self.toks[self.i] if self.i < len(self.toks) else None

    def take(self, expected: str | None = None) -> str:
        tok = self.peek()
        if tok is None:
            raise ParseError(f"unexpected end of rung (expected {expected or 'more'})")
        if expected is not None and tok != expected:
            raise ParseError(f"expected {expected!r}, got {tok!r}")
        self.i += 1
        return tok

    def name(self) -> str:
        tok = self.take()
        if tok in RESERVED or not re.fullmatch(r"[A-Z][A-Z0-9_]*", tok):
            raise ParseError(f"expected a signal name, got {tok!r}")
        return tok

    def expr(self) -> dict:
        args = [self.term()]
        while self.peek() == "OR":
            self.take()
            args.append(self.term())
        return args[0] if len(args) == 1 else {"op": "or", "args": args}

    def term(self) -> dict:
        args = [self.factor()]
        while self.peek() == "AND":
            self.take()
            args.append(self.factor())
        return args[0] if len(args) == 1 else {"op": "and", "args": args}

    def factor(self) -> dict:
        tok = self.peek()
        if tok == "NOT":
            self.take()
            return {"op": "not", "arg": self.factor()}
        if tok == "(":
            self.take()
            e = self.expr()
            self.take(")")
            return e
        if tok == "RISE":
            self.take()
            self.take("(")
            n = self.name()
            self.take(")")
            return {"op": "rise", "name": n}
        if tok in ("TRUE", "FALSE"):
            self.take()
            return {"op": "const", "value": tok == "TRUE"}
        if tok is not None and tok.endswith(".Q"):
            self.take()
            n = tok[:-2]
            if not is_timer_name(n):
                raise ParseError(f"{tok!r}: only timers (T_...) have a .Q output")
            return {"op": "timer", "name": n}
        return {"op": "var", "name": self.name()}


def parse_rung(text: str, rung_id: str = "R00", comment: str | None = None) -> dict:
    """Parse one rung of source text into a Rung dict (see web/src/types.ts)."""
    toks = _tokenize(text)
    if not toks:
        raise ParseError("empty rung")
    p = _Parser(toks)
    rung: dict
    if toks[0] == "TON":
        p.take()
        target = p.take()
        if not is_timer_name(target):
            raise ParseError(f"timer names must look like T_NAME, got {target!r}")
        p.take("(")
        cond = p.expr()
        p.take(",")
        num = p.take()
        if not re.fullmatch(r"\d+(\.\d+)?s", num):
            raise ParseError(f"timer preset must look like 3.0s, got {num!r}")
        p.take(")")
        rung = {"kind": "ton", "target": target, "expr": cond, "pt": float(num[:-1])}
    elif toks[0] in ("SET", "RESET") and len(toks) > 2 and toks[2] == "WHEN":
        kind = p.take().lower()
        target = p.name()
        p.take("WHEN")
        rung = {"kind": kind, "target": target, "expr": p.expr()}
    else:
        target = p.name()
        p.take("=")
        rung = {"kind": "assign", "target": target, "expr": p.expr()}
    if p.peek() is not None:
        raise ParseError(f"unexpected {p.peek()!r} after the end of the rung")
    rung = {"id": rung_id, "text": rung_to_text(rung), **rung}
    if comment:
        rung["comment"] = comment
    return rung


_PREC = {"or": 1, "and": 2, "not": 3}


def expr_to_text(e: dict, parent: int = 0) -> str:
    op = e["op"]
    if op == "var":
        return e["name"]
    if op == "timer":
        return f"{e['name']}.Q"
    if op == "rise":
        return f"RISE({e['name']})"
    if op == "const":
        return "TRUE" if e["value"] else "FALSE"
    if op == "not":
        return f"NOT {expr_to_text(e['arg'], _PREC['not'])}"
    p = _PREC[op]
    s = (" AND " if op == "and" else " OR ").join(expr_to_text(a, p) for a in e["args"])
    return f"({s})" if parent > p else s


def rung_to_text(r: dict) -> str:
    kind, target, body = r["kind"], r["target"], expr_to_text(r["expr"])
    if kind == "assign":
        return f"{target} = {body}"
    if kind in ("set", "reset"):
        return f"{kind.upper()} {target} WHEN {body}"
    return f"TON {target}({body}, {r['pt']:g}s)"


def expr_refs(e: dict, out_vars: list[str] | None = None, out_timers: list[str] | None = None):
    """Names read by an expression, in depth-first order without duplicates."""
    out_vars = [] if out_vars is None else out_vars
    out_timers = [] if out_timers is None else out_timers
    op = e["op"]
    if op in ("var", "rise"):
        if e["name"] not in out_vars:
            out_vars.append(e["name"])
    elif op == "timer":
        if e["name"] not in out_timers:
            out_timers.append(e["name"])
    elif op == "not":
        expr_refs(e["arg"], out_vars, out_timers)
    elif op in ("and", "or"):
        for a in e["args"]:
            expr_refs(a, out_vars, out_timers)
    return out_vars, out_timers


def _literals(e: dict) -> int:
    if e["op"] == "not":
        return _literals(e["arg"])
    if e["op"] in ("and", "or"):
        return sum(_literals(a) for a in e["args"])
    return 1


def parse_program(source: str) -> list[dict]:
    """Parse a program written one rung per line as `R01  <rung>  # comment`."""
    rungs = []
    for line in source.strip().splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        comment = None
        if "#" in line:
            line, comment = line.split("#", 1)
            comment = comment.strip() or None
        rid, text = line.split(None, 1)
        rungs.append(parse_rung(text, rid, comment))
    return rungs


def validate_program(rungs: list[dict]) -> list[str]:
    """Static checks that every accepted program must pass. Returns a list of problems."""
    problems: list[str] = []
    if len(rungs) > MAX_RUNGS:
        problems.append(f"too many rungs ({len(rungs)} > {MAX_RUNGS})")
    ids = [r["id"] for r in rungs]
    if len(set(ids)) != len(ids):
        problems.append("duplicate rung ids")
    assigned: set[str] = set()
    timers: dict[str, float] = {}
    coils: set[str] = set()
    for r in rungs:
        t = r["target"]
        if t in INPUTS:
            problems.append(f"{r['id']}: {t} is an input and cannot be written")
        if r["kind"] == "ton":
            if t in timers:
                problems.append(f"{r['id']}: timer {t} is defined twice")
            pt = r.get("pt", 0)
            if not PT_MIN <= pt <= PT_MAX:
                problems.append(f"{r['id']}: timer preset {pt}s outside {PT_MIN}-{PT_MAX}s")
            timers[t] = pt
        else:
            if is_timer_name(t):
                problems.append(f"{r['id']}: {t} looks like a timer; write timers with TON")
            if r["kind"] == "assign":
                if t in assigned:
                    problems.append(f"{r['id']}: {t} is assigned by more than one rung")
                assigned.add(t)
            if t not in OUTPUTS:
                coils.add(t)
        if _literals(r["expr"]) > MAX_LITERALS:
            problems.append(f"{r['id']}: more than {MAX_LITERALS} contacts in one rung")
        _, used_timers = expr_refs(r["expr"])
        for tn in used_timers:
            if tn not in {x["target"] for x in rungs if x["kind"] == "ton"}:
                problems.append(f"{r['id']}: {tn}.Q is read but timer {tn} is never defined")
    if len(coils) > MAX_COILS:
        problems.append(f"too many internal coils ({len(coils)} > {MAX_COILS})")
    if len(timers) > MAX_TIMERS:
        problems.append(f"too many timers ({len(timers)} > {MAX_TIMERS})")
    if "MOTOR" not in assigned and not any(r["target"] == "MOTOR" for r in rungs):
        problems.append("nothing drives MOTOR")
    return problems


def program_to_text(rungs: list[dict]) -> str:
    lines = []
    for r in rungs:
        line = f"{r['id']}  {r['text']}"
        if r.get("comment"):
            line += f"    # {r['comment']}"
        lines.append(line)
    return "\n".join(lines)


@dataclass
class Edit:
    op: str  # "replace" | "insert_after" | "delete"
    id: str  # rung id the edit refers to ("START" inserts at the top)
    text: str = ""


def apply_edits(rungs: list[dict], edits: list[Edit]) -> list[dict]:
    """Apply a patch. New rungs get fresh ids. Raises ParseError on any invalid edit."""
    out = [dict(r) for r in rungs]
    used = {r["id"] for r in out}

    def fresh_id() -> str:
        n = 1
        while f"R{n:02d}" in used:
            n += 1
        used.add(f"R{n:02d}")
        return f"R{n:02d}"

    for e in edits:
        idx = next((i for i, r in enumerate(out) if r["id"] == e.id), None)
        if e.op == "insert_after" and e.id == "START":
            idx = -1
        if idx is None:
            raise ParseError(f"no rung with id {e.id!r}")
        if e.op == "replace":
            out[idx] = parse_rung(e.text, out[idx]["id"])
        elif e.op == "insert_after":
            out.insert(idx + 1, parse_rung(e.text, fresh_id()))
        elif e.op == "delete":
            out.pop(idx)
        else:
            raise ParseError(f"unknown edit op {e.op!r}")
    return out

"""PLC scan engine, conveyor plant and safety monitors. Mirrors web/src/sim (plc.ts, plant.ts,
monitors.ts); scripts/parity checks both sides produce identical traces.

Scan semantics: rungs run top to bottom every scan; an expression reads the current memory (a coil
written by an earlier rung this scan is already updated); RISE(X) compares against the memory
snapshot taken at the end of the previous scan.
"""

from __future__ import annotations

from .lang import INPUTS, OUTPUTS, expr_refs

DT = 0.1


def initial_inputs() -> dict[str, int]:
    m = {n: 0 for n in INPUTS}
    m["GUARD_CLOSED"] = 1
    return m


def compile_expr(e: dict):
    """Compile an expression AST into a function of the PLC (fast enough for model checking)."""
    op = e["op"]
    if op == "var":
        n = e["name"]
        return lambda m: m.sig.get(n, 0) == 1
    if op == "timer":
        n = e["name"]
        return lambda m: m.timer_q(n)
    if op == "rise":
        n = e["name"]
        return lambda m: m.sig.get(n, 0) == 1 and m.prev.get(n, 0) != 1
    if op == "const":
        v = bool(e["value"])
        return lambda m: v
    if op == "not":
        f = compile_expr(e["arg"])
        return lambda m: not f(m)
    fs = [compile_expr(a) for a in e["args"]]
    if op == "and":
        return lambda m: all(f(m) for f in fs)
    return lambda m: any(f(m) for f in fs)


def program_coils(rungs: list[dict]) -> list[str]:
    """Internal coils (not inputs, outputs or timers), in order of first appearance."""
    out: list[str] = []

    def add(n: str) -> None:
        if n not in INPUTS and n not in OUTPUTS and n not in out:
            out.append(n)

    for r in rungs:
        if r["kind"] != "ton":
            add(r["target"])
    for r in rungs:
        for n in expr_refs(r["expr"])[0]:
            add(n)
    return out


def program_timers(rungs: list[dict]) -> list[tuple[str, float]]:
    out: list[tuple[str, float]] = []
    for r in rungs:
        if r["kind"] == "ton" and all(t[0] != r["target"] for t in out):
            out.append((r["target"], float(r.get("pt", 0.0))))
    return out


class Plc:
    def __init__(self, rungs: list[dict]):
        self.rungs = rungs
        self.coils = program_coils(rungs)
        self.timer_defs = program_timers(rungs)
        self.compiled = [(r["kind"], r["target"], compile_expr(r["expr"]), float(r.get("pt", 0.0))) for r in rungs]
        self.sig: dict[str, int] = dict(initial_inputs())
        self.prev: dict[str, int] = dict(initial_inputs())
        for n in OUTPUTS:
            self.sig[n] = self.prev[n] = 0
        for n in self.coils:
            self.sig[n] = self.prev[n] = 0
        # timer name -> [et, q]
        self.timers: dict[str, list] = {n: [0.0, False] for n, _ in self.timer_defs}

    def timer_q(self, name: str) -> bool:
        t = self.timers.get(name)
        return bool(t and t[1])

    def scan(self, inputs: dict[str, int], dt: float = DT) -> None:
        for n in INPUTS:
            self.sig[n] = 1 if inputs.get(n) == 1 else 0
        for kind, target, f, pt in self.compiled:
            v = f(self)
            if kind == "assign":
                self.sig[target] = 1 if v else 0
            elif kind == "set":
                if v:
                    self.sig[target] = 1
            elif kind == "reset":
                if v:
                    self.sig[target] = 0
            else:  # ton
                tm = self.timers[target]
                tm[0] = min(tm[0] + dt, pt) if v else 0
                tm[1] = tm[0] >= pt - 1e-9
        self.prev = dict(self.sig)

    def outputs(self) -> dict[str, int]:
        return {n: (1 if self.sig.get(n) == 1 else 0) for n in OUTPUTS}

    def coil_values(self) -> dict[str, int]:
        return {n: (1 if self.sig.get(n) == 1 else 0) for n in self.coils}

    def timer_values(self) -> dict[str, float]:
        return {n: self.timers[n][0] for n, _ in self.timer_defs}


# ---------------------------------------------------------------- plant (integer millimetres)

GEO = {
    "belt_end": 4000,
    "step": 50,  # mm per scan while MOTOR = 1 (0.5 m/s at dt = 0.1 s)
    "box_len": 400,
    "spawn_x": 200,
    "pe_in": 300,
    "pe_end": 3700,
    "sense": 200,  # a photo-eye sees a box whose centre is within this distance
    "drop_x": 3900,
    "pick_x": 3700,
    "pick_half": 250,
}


class Plant:
    def __init__(self) -> None:
        self.boxes: list[dict] = []
        self.next_id = 1
        self.stuck: dict[str, int] = {}

    def infeed_clear(self) -> bool:
        return not any(b["state"] == "belt" and abs(b["x"] - GEO["spawn_x"]) < GEO["box_len"] for b in self.boxes)

    def spawn(self) -> dict | None:
        if not self.infeed_clear():
            return None
        b = {"id": self.next_id, "x": GEO["spawn_x"], "state": "belt"}
        self.next_id += 1
        self.boxes.append(b)
        return b

    def at_pick(self) -> dict | None:
        best = None
        for b in self.boxes:
            if b["state"] == "belt" and abs(b["x"] - GEO["pick_x"]) <= GEO["pick_half"] and (best is None or b["x"] > best["x"]):
                best = b
        return best

    def pick(self) -> dict | None:
        b = self.at_pick()
        if b:
            b["state"] = "picked"
        return b

    def sees(self, pos: int) -> int:
        return 1 if any(b["state"] == "belt" and abs(b["x"] - pos) <= GEO["sense"] for b in self.boxes) else 0

    def sensors(self) -> dict[str, int]:
        return {
            "PE_IN": self.stuck.get("PE_IN", self.sees(GEO["pe_in"])),
            "PE_END": self.stuck.get("PE_END", self.sees(GEO["pe_end"])),
        }

    def move(self) -> list[dict]:
        belt = sorted((b for b in self.boxes if b["state"] == "belt"), key=lambda b: -b["x"])
        dropped = []
        ahead = None
        for b in belt:
            nx = b["x"] + GEO["step"]
            if ahead is not None:
                nx = min(nx, ahead["x"] - GEO["box_len"])
            b["x"] = nx
            if b["x"] > GEO["drop_x"]:
                b["state"] = "dropped"
                dropped.append(b)
            ahead = b
        return dropped

    def snapshot(self) -> list[dict]:
        return [{"id": b["id"], "x": b["x"] / 1000, "state": b["state"]} for b in self.boxes]


# ---------------------------------------------------------------- safety monitors

RULE_IDS = ("S1", "S2", "S3", "S4", "S5", "S6", "S7")
RULE_MESSAGES = {
    "S1": "Motor running while the E-stop is pressed",
    "S2": "Motor running with the guard door open",
    "S3": "Motor running while STOP is pressed",
    "S4": "Motor restarted without a START press",
    "S5": "E-stop cleared without RESET",
    "S6": "Motor running with a box at the pick position",
    "S7": "Infeed jam not detected within 3.5 s",
}


def monitor_conditions(state: tuple, inp: dict, out: dict) -> tuple[tuple, dict[str, bool]]:
    """Pure observer step shared by the simulator and the model checker.

    state = (armed, lock, jam, prev_start, prev_reset). Returns (new_state, rule -> violated)."""
    armed, lock, jam, prev_start, prev_reset = state
    START = inp["START"] == 1
    STOP = inp["STOP"] == 1
    ESTOP = inp["ESTOP"] == 1
    RESET = inp["RESET"] == 1
    GUARD = inp["GUARD_CLOSED"] == 1
    PE_IN = inp["PE_IN"] == 1
    PE_END = inp["PE_END"] == 1
    MOTOR = out["MOTOR"] == 1
    RED = out["LAMP_RED"] == 1
    rise_start = START and prev_start == 0
    rise_reset = RESET and prev_reset == 0
    lock_b = (lock == 1 or ESTOP) and not ((not ESTOP) and rise_reset)
    armed_b = (armed == 1 or (rise_start and not lock_b)) and not STOP and not ESTOP and GUARD and not RED
    jam = jam + 1 if (MOTOR and PE_IN) else 0
    cond = {
        "S1": ESTOP and MOTOR,
        "S2": (not GUARD) and MOTOR,
        "S3": STOP and MOTOR,
        "S4": MOTOR and not armed_b,
        "S5": lock_b and (MOTOR or not RED),
        "S6": PE_END and MOTOR,
        "S7": jam > 35,
    }
    return (1 if armed_b else 0, 1 if lock_b else 0, jam, 1 if START else 0, 1 if RESET else 0), cond


class Monitor:
    def __init__(self) -> None:
        self.state = (0, 0, 0, 0, 0)
        self.active: dict[str, bool] = {}

    def check(self, t: float, inp: dict, out: dict) -> list[dict]:
        self.state, cond = monitor_conditions(self.state, inp, out)
        found = []
        for rid in RULE_IDS:
            v = cond[rid]
            if v and not self.active.get(rid):
                found.append({"rule": rid, "t": t, "message": RULE_MESSAGES[rid]})
            self.active[rid] = v
        return found

"""The digital twin: PLC + conveyor plant + safety monitors, stepped one scan at a time.
Mirrors web/src/sim/sim.ts. A scenario is a script of timed operator actions and plant events."""

from __future__ import annotations

from .engine import DT, Monitor, Plant, Plc, initial_inputs
from .lang import OUTPUTS

PRESS_LABEL = {
    "START": "Operator presses START",
    "STOP": "Operator presses STOP",
    "RESET": "Operator presses RESET",
    "ESTOP": "E-stop pressed",
}


def round1(x: float) -> float:
    # Math.round(x * 10) / 10 in JS (round half up), for parity with the viewer.
    import math

    return math.floor(x * 10 + 0.5) / 10


def _set_label(name: str, v: int) -> str:
    if name == "ESTOP":
        return "E-stop pressed" if v else "E-stop released"
    if name == "GUARD_CLOSED":
        return "Guard door closed" if v else "Guard door opened"
    return f"Operator holds {name}" if v else f"Operator releases {name}"


class Sim:
    def __init__(self, program: list[dict], autofeed_every: float | None = None, autopick_after: float | None = None):
        self.plc = Plc(program)
        self.plant = Plant()
        self.mon = Monitor()
        self.inputs = initial_inputs()
        self.k = 0
        self.autofeed_every = autofeed_every
        self.autopick_after = autopick_after
        self.last_out = {n: 0 for n in OUTPUTS}
        self.pick_wait = 0
        self.releases: list[tuple[str, float]] = []
        self.last_spawn_t = float("-inf")
        self.pending: list[dict] = []

    @property
    def t(self) -> float:
        return round1(self.k * DT)

    def _ev(self, kind: str, label: str) -> None:
        self.pending.append({"t": self.t, "kind": kind, "label": label})

    def press(self, name: str, duration: float = 0.3, start: float | None = None) -> None:
        start = self.t if start is None else start
        self.releases = [r for r in self.releases if r[0] != name]
        self.inputs[name] = 1
        self.releases.append((name, start + duration))
        self._ev("press", PRESS_LABEL.get(name, f"Operator presses {name}"))

    def set(self, name: str, v: int) -> None:
        if self.inputs.get(name) == v:
            return
        self.inputs[name] = v
        self._ev("set", _set_label(name, v))

    def spawn(self) -> bool:
        b = self.plant.spawn()
        if b:
            self._ev("spawn", "Box placed on infeed")
        return b is not None

    def pick(self) -> bool:
        b = self.plant.pick()
        if b:
            self._ev("pick", "Robot picks box")
        return b is not None

    def stick(self, sensor: str, v: int) -> None:
        self.plant.stuck[sensor] = v
        self._ev("stick", f"{sensor} sensor stuck {'ON' if v else 'OFF'}")

    def unstick(self, sensor: str) -> None:
        if sensor not in self.plant.stuck:
            return
        del self.plant.stuck[sensor]
        self._ev("unstick", f"{sensor} sensor repaired")

    def apply_event(self, e: dict) -> None:
        kind = e["kind"]
        if kind == "press" and e.get("input"):
            self.press(e["input"], e.get("duration", 0.3), e["t"])
        elif kind == "set" and e.get("input"):
            self.set(e["input"], e.get("value", 1))
        elif kind == "spawn":
            self.spawn()
        elif kind == "pick":
            self.pick()
        elif kind == "stick" and e.get("sensor"):
            self.stick(e["sensor"], e.get("value", 1))
        elif kind == "unstick" and e.get("sensor"):
            self.unstick(e["sensor"])

    def step(self, apply_events=None) -> tuple[dict, list[dict], list[dict]]:
        t = self.t
        keep = []
        for name, at in self.releases:
            if t >= at:
                self.inputs[name] = 0
                self._ev("release", f"{name} released")
            else:
                keep.append((name, at))
        self.releases = keep
        if apply_events:
            apply_events(self, t)
        feed = self.autofeed_every
        if feed is not None and feed > 0 and t - self.last_spawn_t >= feed and self.plant.infeed_clear():
            if self.spawn():
                self.last_spawn_t = t
        pick_after = self.autopick_after
        if pick_after is not None and pick_after >= 0:
            b = self.plant.at_pick()
            if b and self.last_out["MOTOR"] == 0:
                self.pick_wait += 1
                if self.pick_wait >= round(pick_after / DT):
                    self.pick()
                    self.pick_wait = 0
            else:
                self.pick_wait = 0

        s = self.plant.sensors()
        self.inputs["PE_IN"] = s["PE_IN"]
        self.inputs["PE_END"] = s["PE_END"]

        self.plc.scan(self.inputs, DT)
        out = self.plc.outputs()
        violations = self.mon.check(t, self.inputs, out)

        frame = {
            "t": t,
            "in": dict(self.inputs),
            "out": out,
            "coil": self.plc.coil_values(),
            "timer": self.plc.timer_values(),
            "boxes": self.plant.snapshot(),
        }
        if self.plant.stuck:
            frame["stuck"] = dict(self.plant.stuck)

        if out["MOTOR"] == 1:
            for b in self.plant.move():
                violations.append({"rule": "DROP", "t": t, "message": f"Box #{b['id']} pushed off the end of the belt"})
                self._ev("drop", f"Box #{b['id']} falls off the end")
        self.last_out = out
        self.k += 1
        events, self.pending = self.pending, []
        return frame, violations, events


def run_scenario(program: list[dict], sc: dict) -> dict:
    """Run a scripted scenario and record its full trace (see Trace in web/src/types.ts)."""
    opts = sc.get("options") or {}
    sim = Sim(program, opts.get("autofeed_every"), opts.get("autopick_after"))
    n = round(sc["duration"] / DT)
    applied = [False] * len(sc["events"])

    def apply(s: Sim, t: float) -> None:
        for i, e in enumerate(sc["events"]):
            if not applied[i] and e["t"] <= t + 1e-9:
                applied[i] = True
                s.apply_event(e)

    trace = {"dt": DT, "frames": [], "violations": [], "events": []}
    for _ in range(n):
        frame, violations, events = sim.step(apply)
        trace["frames"].append(frame)
        trace["violations"].extend(violations)
        trace["events"].extend(events)
    return trace

