"""Verification: scripted tests, randomized fuzzing, and a model checker that proves safety rules.

The model checker explores every reachable state of the PLC program under every possible input in
every scan (all 7 inputs are free, so stuck sensors and any operator behaviour are covered). Timers are
abstracted: a running timer may finish at any later scan. That over-approximates real timing, so a
rule proven here holds for every input sequence of any length and every timer preset."""

from __future__ import annotations

import itertools
from collections import deque

from .engine import DT, compile_expr, initial_inputs, monitor_conditions, program_coils, program_timers
from .lang import INPUTS, OUTPUTS, expr_refs
from .sim import run_scenario

SAFETY_RULES = ("S1", "S2", "S3", "S4", "S5", "S6", "S7")
PROOF_RULES = ("S1", "S2", "S3", "S4", "S5", "S6")


# ---------------------------------------------------------------- scripted tests

def run_test(program: list[dict], test: dict) -> dict:
    trace = run_scenario(program, test)
    frames = trace["frames"]
    failures = []
    for ex in test["expect"]:
        k = min(range(len(frames)), key=lambda i: abs(frames[i]["t"] - ex["t"]))
        f = frames[k]
        got = f["in"].get(ex["sig"], f["out"].get(ex["sig"], f["coil"].get(ex["sig"])))
        if got != ex["val"]:
            failures.append({"t": ex["t"], "kind": "expect", "message": f"expected {ex['sig']}={ex['val']} at t={ex['t']}s, got {got}"})
    for v in trace["violations"]:
        failures.append({"t": v["t"], "kind": "violation", "rule": v["rule"], "message": f"{v['rule']} violated at t={v['t']}s: {v['message']}"})
    picked = sum(1 for b in (frames[-1]["boxes"] if frames else []) if b["state"] == "picked")
    if picked < test.get("min_picked", 0):
        failures.append({"t": test["duration"], "kind": "expect", "message": f"expected at least {test['min_picked']} box(es) picked, got {picked}"})
    failures.sort(key=lambda x: x["t"])
    return {"id": test["id"], "title": test["title"], "passed": not failures, "failures": failures, "trace": trace}


def run_suite(program: list[dict], tests: list[dict]) -> list[dict]:
    return [run_test(program, t) for t in tests]


def fuzz(program: list[dict], scenarios: list[dict]) -> dict:
    by_rule: dict[str, int] = {}
    bad_episodes = 0
    first: dict[str, dict] = {}
    for sc in scenarios:
        tr = run_scenario(program, sc)
        rules = {v["rule"] for v in tr["violations"]}
        if rules:
            bad_episodes += 1
        for v in tr["violations"]:
            by_rule[v["rule"]] = by_rule.get(v["rule"], 0) + 1
            first.setdefault(v["rule"], {"scenario": sc["id"], "t": v["t"], "message": v["message"]})
    return {"episodes": len(scenarios), "violations": bad_episodes, "by_rule": by_rule, "examples": first}


def trace_window(trace: dict, t_from: float, t_to: float, signals: list[str] | None = None) -> str:
    """A compact scan table for the agent: one line per scan in [t_from, t_to]."""
    frames = [f for f in trace["frames"] if t_from - 1e-9 <= f["t"] <= t_to + 1e-9]
    if not frames:
        return "(no scans in that window)"
    default = list(INPUTS) + list(OUTPUTS)
    coils = list(frames[0]["coil"].keys())
    timers = list(frames[0]["timer"].keys())
    cols = signals or (default + coils)
    head = "t     " + " ".join(f"{c[:8]:>8}" for c in cols) + "".join(f" {tn:>8}" for tn in timers) + "  boxes(x m)"
    lines = [head]
    for f in frames:
        vals = []
        for c in cols:
            v = f["in"].get(c, f["out"].get(c, f["coil"].get(c, "?")))
            vals.append(f"{v:>8}")
        tv = "".join(f" {f['timer'][tn]:>8.1f}" for tn in timers)
        boxes = ",".join(f"{b['x']:.2f}{'' if b['state'] == 'belt' else '(' + b['state'] + ')'}" for b in f["boxes"]) or "-"
        lines.append(f"{f['t']:<5.1f} " + " ".join(vals) + tv + f"  {boxes}")
    return "\n".join(lines)


# ---------------------------------------------------------------- model checker

OFF, RUNNING, DONE = 0, 1, 2


class _Mem:
    __slots__ = ("sig", "prev", "tq")

    def __init__(self, sig, prev, tq):
        self.sig = sig
        self.prev = prev
        self.tq = tq

    def timer_q(self, name):
        return self.tq.get(name, OFF) == DONE


def prove(program: list[dict], max_states: int = 250_000) -> dict:
    coils = program_coils(program)
    timers = program_timers(program)
    pts = dict(timers)
    tnames = [t for t, _ in timers]
    state_sigs = list(OUTPUTS) + coils
    rise_inputs = sorted({n for r in program for n in _rise_names(r["expr"]) if n in INPUTS} | {"START", "RESET"})
    rungs = [(r["kind"], r["target"], compile_expr(r["expr"])) for r in program]
    init_in = initial_inputs()

    init = (tuple(0 for _ in state_sigs), tuple(init_in[n] for n in rise_inputs), tuple(OFF for _ in tnames), (0, 0))
    vectors = [dict(zip(INPUTS, bits)) for bits in itertools.product((0, 1), repeat=len(INPUTS))]

    def successors(state, inp):
        sig_bits, prev_bits, tstates, mon = state
        sig = dict(zip(state_sigs, sig_bits))
        prev = dict(zip(state_sigs, sig_bits))
        prev.update(zip(rise_inputs, prev_bits))
        for n in INPUTS:
            prev.setdefault(n, init_in[n])
        sig.update(inp)
        results = []

        def run(i, sig, tq):
            while i < len(rungs):
                kind, target, f = rungs[i]
                v = f(_Mem(sig, prev, tq))
                if kind == "assign":
                    sig[target] = 1 if v else 0
                elif kind == "set":
                    if v:
                        sig[target] = 1
                elif kind == "reset":
                    if v:
                        sig[target] = 0
                else:
                    cur = tq[target]
                    if not v:
                        tq[target] = OFF
                    elif cur == OFF:
                        tq[target] = DONE if pts[target] <= DT + 1e-9 else RUNNING
                    elif cur == RUNNING:
                        # Abstract time: the timer may still be running, or may have just finished.
                        sig2, tq2 = dict(sig), dict(tq)
                        tq2[target] = DONE
                        run(i + 1, sig2, tq2)
                        tq[target] = RUNNING
                i += 1
            results.append((sig, tq))

        run(0, sig, dict(zip(tnames, tstates)))
        out = []
        for sig2, tq2 in results:
            outs = {n: sig2.get(n, 0) for n in OUTPUTS}
            mstate, cond = monitor_conditions((mon[0], mon[1], 0, prev.get("START", 0), prev.get("RESET", 0)), inp, outs)
            nxt = (tuple(sig2.get(n, 0) for n in state_sigs), tuple(inp[n] for n in rise_inputs), tuple(tq2[t] for t in tnames), (mstate[0], mstate[1]))
            out.append((nxt, outs, cond))
        return out

    parent: dict = {init: None}
    queue = deque([init])
    found: dict[str, tuple] = {}
    motor_reachable = False
    explored = 0
    while queue and len(parent) < max_states:
        s = queue.popleft()
        explored += 1
        for inp in vectors:
            for nxt, outs, cond in successors(s, inp):
                if outs["MOTOR"]:
                    motor_reachable = True
                for rid in PROOF_RULES:
                    if cond[rid] and rid not in found:
                        found[rid] = (s, inp, outs)
                if nxt not in parent:
                    parent[nxt] = (s, inp, outs)
                    queue.append(nxt)
    complete = not queue

    def path_to(s, last_inp, last_out):
        steps = []
        while parent[s] is not None:
            ps, pinp, pout = parent[s]
            steps.append((pinp, pout))
            s = ps
        steps.reverse()
        steps.append((last_inp, last_out))
        return [{"t": round(i * DT, 1), "in": dict(inp), "out": dict(out)} for i, (inp, out) in enumerate(steps)]

    results = []
    for rid in PROOF_RULES:
        if rid in found:
            s, inp, outs = found[rid]
            results.append({"rule": rid, "status": "violated", "states_explored": len(parent), "counterexample": path_to(s, inp, outs)})
        else:
            results.append({"rule": rid, "status": "proven" if complete else "bounded", "states_explored": len(parent)})
    return {"complete": complete, "states": len(parent), "motor_reachable": motor_reachable, "results": results}


def _rise_names(e: dict) -> list[str]:
    if e["op"] == "rise":
        return [e["name"]]
    if e["op"] == "not":
        return _rise_names(e["arg"])
    if e["op"] in ("and", "or"):
        return [n for a in e["args"] for n in _rise_names(a)]
    return []


def counterexample_text(cex: list[dict]) -> str:
    cols = list(INPUTS) + ["MOTOR", "LAMP_RED"]
    lines = ["scan " + " ".join(f"{c[:8]:>8}" for c in cols)]
    for i, st in enumerate(cex):
        vals = [st["in"].get(c, st["out"].get(c)) for c in cols]
        lines.append(f"{i:<4} " + " ".join(f"{v:>8}" for v in vals))
    return "\n".join(lines)

"""LLM access for the agent.

Two backends behind one interface:
- "openai": any OpenAI-compatible endpoint (the neatHack LiteLLM proxy, or Anthropic's), with native
  tool calling. neatlogs instruments these calls automatically.
- "claude-cli": the local Claude Code CLI in print mode, used when no API key is configured. Tools are
  described in the prompt and the model answers with one JSON tool call.
"""

from __future__ import annotations

import json
import os
import re
import subprocess
import tempfile
import time
from dataclasses import dataclass, field

# USD per million tokens (input, output), for cost estimates when the backend does not report cost.
PRICES = {"claude-sonnet": (3.0, 15.0), "claude-opus": (15.0, 75.0), "claude-haiku": (1.0, 5.0), "nova": (0.8, 3.2)}


def price_for(model: str) -> tuple[float, float]:
    for k, v in PRICES.items():
        if k in model:
            return v
    return PRICES["claude-sonnet"]


@dataclass
class ToolCall:
    id: str
    name: str
    args: dict


@dataclass
class Reply:
    text: str
    calls: list[ToolCall]
    input_tokens: int = 0
    output_tokens: int = 0
    cost_usd: float = 0.0
    latency_s: float = 0.0
    raw: dict = field(default_factory=dict)


class OpenAIBackend:
    name = "openai"

    def __init__(self, model: str):
        from openai import OpenAI  # imported late so neatlogs.init() can instrument it first

        self.client = OpenAI(base_url=os.environ.get("LLM_BASE_URL") or None, api_key=os.environ["LLM_API_KEY"])
        self.model = model

    def chat(self, system: str, messages: list[dict], tools: list[dict]) -> Reply:
        t0 = time.time()
        resp = self.client.chat.completions.create(
            model=self.model,
            messages=[{"role": "system", "content": system}, *messages],
            tools=[{"type": "function", "function": t} for t in tools],
            tool_choice="auto",
            temperature=0.2,
            max_tokens=2000,
        )
        msg = resp.choices[0].message
        calls = []
        for tc in msg.tool_calls or []:
            try:
                args = json.loads(tc.function.arguments or "{}")
            except json.JSONDecodeError:
                args = {"_raw": tc.function.arguments}
            calls.append(ToolCall(tc.id, tc.function.name, args))
        u = resp.usage
        pin, pout = price_for(self.model)
        cost = (u.prompt_tokens * pin + u.completion_tokens * pout) / 1e6 if u else 0.0
        return Reply(msg.content or "", calls, u.prompt_tokens if u else 0, u.completion_tokens if u else 0, cost, time.time() - t0)

    def assistant_message(self, reply: Reply) -> dict:
        m: dict = {"role": "assistant", "content": reply.text or None}
        if reply.calls:
            m["tool_calls"] = [
                {"id": c.id, "type": "function", "function": {"name": c.name, "arguments": json.dumps(c.args)}} for c in reply.calls
            ]
        return m

    def tool_message(self, call: ToolCall, content: str) -> dict:
        return {"role": "tool", "tool_call_id": call.id, "content": content}


class ClaudeCliBackend:
    """Claude Code in print mode. Stateless: the whole conversation is replayed each call."""

    name = "claude-cli"

    def __init__(self, model: str = "sonnet"):
        self.model = model
        self.workdir = tempfile.mkdtemp(prefix="stopprove-llm-")
        self.n = 0

    def chat(self, system: str, messages: list[dict], tools: list[dict]) -> Reply:
        tool_doc = "\n".join(
            f"- {t['name']}: {t['description']}\n  args schema: {json.dumps(t['parameters'])}" for t in tools
        )
        sys_prompt = (
            system
            + "\n\nYou act only through tools. Available tools:\n"
            + tool_doc
            + "\n\nReply with exactly one JSON object and nothing else:\n"
            + '{"thought": "<one or two sentences of reasoning>", "tool": "<tool name>", "args": {...}}'
        )
        convo = []
        for m in messages:
            if m["role"] == "user":
                convo.append(f"USER:\n{m['content']}")
            elif m["role"] == "assistant":
                convo.append(f"YOU:\n{m['content']}")
            else:
                convo.append(f"TOOL RESULT ({m.get('name', 'tool')}):\n{m['content']}")
        prompt = "\n\n".join(convo) + "\n\nYour next JSON action:"
        t0 = time.time()
        proc = subprocess.run(
            ["claude", "-p", "--output-format", "json", "--model", self.model, "--max-turns", "1",
             "--tools", "", "--strict-mcp-config", "--setting-sources", "user", "--no-session-persistence",
             "--system-prompt", sys_prompt],
            input=prompt, capture_output=True, text=True, encoding="utf-8", cwd=self.workdir, timeout=300,
        )
        latency = time.time() - t0
        if proc.returncode != 0 and not proc.stdout.strip():
            raise RuntimeError(f"claude CLI failed: {proc.stderr.strip()[:500]}")
        data = json.loads(proc.stdout)
        text = data.get("result", "") or ""
        usage = data.get("usage", {}) or {}
        tin = int(usage.get("input_tokens", 0)) + int(usage.get("cache_read_input_tokens", 0)) + int(usage.get("cache_creation_input_tokens", 0))
        tout = int(usage.get("output_tokens", 0))
        cost = float(data.get("total_cost_usd") or 0.0)
        self.n += 1
        calls = []
        thought = text
        m = re.search(r"\{.*\}", text, re.S)
        if m:
            try:
                obj = json.loads(m.group(0))
                thought = obj.get("thought", "")
                if obj.get("tool"):
                    calls.append(ToolCall(f"call_{self.n}", obj["tool"], obj.get("args") or {}))
            except json.JSONDecodeError:
                pass
        return Reply(thought, calls, tin, tout, cost, latency, data)

    def assistant_message(self, reply: Reply) -> dict:
        if reply.calls:
            c = reply.calls[0]
            return {"role": "assistant", "content": json.dumps({"thought": reply.text, "tool": c.name, "args": c.args})}
        return {"role": "assistant", "content": reply.text}

    def tool_message(self, call: ToolCall, content: str) -> dict:
        return {"role": "tool", "name": call.name, "content": content}


def make_backend(prefer: str | None = None):
    """OpenAI-compatible endpoint when a key is configured, otherwise the local Claude CLI."""
    prefer = prefer or os.environ.get("LLM_BACKEND")
    if prefer != "claude-cli" and os.environ.get("LLM_API_KEY"):
        return OpenAIBackend(os.environ.get("LLM_MODEL", "claude-sonnet-4.6"))
    return ClaudeCliBackend(os.environ.get("CLAUDE_CLI_MODEL", "sonnet"))

"""The agent's workbench: tools over the digital twin, and the program versions it creates.

The agent never sees the seeded fault labels or the held-out tests. It sees the operating rules, the
program, the visible tests, and (in v2) counterexamples, custom simulations and the model checker."""

from __future__ import annotations

import json
import time

from .plc.cell import LANGUAGE_DOC, SIGNALS_DOC, SPEC, VISIBLE_TESTS
from .plc.lang import Edit, ParseError, apply_edits, program_to_text, validate_program
from .plc.sim import run_scenario
from .plc.verify import counterexample_text, prove, run_suite, trace_window

MAX_EDITS = 4


def _schema(props: dict, required: list[str] | None = None) -> dict:
    return {"type": "object", "properties": props, "required": required or []}


